def build_simple_cache(now_fn: "Callable[[], float] | None" = None) -> "SimpleCache":
    """Create an in-memory TTL cache with an injectable clock.

    This factory returns a cache object that provides the following methods:

    - set(key, value, ttl_seconds): Store a value with TTL in seconds.
      * ttl_seconds must be non-negative.
      * ttl_seconds == 0 means the entry is immediately expired.
      * Overwriting an existing key replaces both value and expiration.

    - get(key): Return the stored value if present and not expired; otherwise return None.
      Expired entries are purged on access.

    - has(key): Return True if the key exists and is not expired; otherwise False.
      Expired entries are purged on access.

    - delete(key): Remove a key if present and not expired. Returns True if removed, else False.
      (If the key is already expired, it behaves like a miss and returns False.)

    - clear(): Remove all entries.

    Time handling:
    - If now_fn is provided, it must return the current time as seconds (float).
    - If now_fn is None, the cache uses time.time.

    The cache is designed to be tested deterministically by injecting now_fn.
    """
    from typing import Any, Callable

    if now_fn is None:
        import time
        _now = time.time
    else:
        _now = now_fn

    class SimpleCache:
        def __init__(self, now_callable: Callable[[], float]):
            self._now = now_callable
            # key -> (value, expires_at)
            self._store: dict[str, tuple[Any, float]] = {}

        def _purge_if_expired(self, key: str) -> None:
            if key not in self._store:
                return
            _, expires_at = self._store[key]
            if self._now() >= expires_at:
                del self._store[key]

        def set(self, key: str, value: Any, ttl_seconds: float) -> None:
            if ttl_seconds < 0:
                raise ValueError("ttl_seconds must be non-negative")
            expires_at = self._now() + float(ttl_seconds)
            self._store[key] = (value, expires_at)

        def get(self, key: str):
            self._purge_if_expired(key)
            if key not in self._store:
                return None
            return self._store[key][0]

        def has(self, key: str) -> bool:
            self._purge_if_expired(key)
            return key in self._store

        def delete(self, key: str) -> bool:
            self._purge_if_expired(key)
            if key in self._store:
                del self._store[key]
                return True
            return False

        def clear(self) -> None:
            self._store.clear()

    return SimpleCache(_now)

